  outline: 2px solid var(--brand);
  outline-offset: 2px;
}

/* Option text */
.option-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.option-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.3;
}

.option-desc {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ── Error message ── */
.error-msg {
  font-size: 0.8125rem;
  color: var(--error);
  margin-top: 10px;
  min-height: 18px;
  font-weight: 500;
}

.form-field.has-error .radio-group {
  border-radius: var(--radius-md);
  outline: 2px solid var(--error);
  outline-offset: 3px;
}

