}

.submit-btn:hover {
  background: var(--brand-dark);
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.4);
}

.submit-btn:active {
  transform: scale(0.98);
}

.submit-btn:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 3px;
}

