  font-size: 0.875rem;
  font-weight: 500;
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
  opacity: 0;
  pointer-events: none;
  transition: opacity 300ms ease, transform 300ms ease;
  white-space: nowrap;
}

.success-toast svg {
  color: var(--success);
  flex-shrink: 0;
}

.success-toast.visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

