+const form = document.getElementById("preferences-form");
+const errorMsg = document.getElementById("error-msg");
+const formField = document.querySelector(".form-field");
+const toast = document.getElementById("success-toast");
+const toastMessage = document.getElementById("toast-message");
+
+const LABELS = {
+  email: "Email",
+  sms: "SMS",
+  push: "Push Notifications",
+};
+
+let toastTimer = null;
+
+form.addEventListener("submit", (e) => {
+  e.preventDefault();
+
+  const selected = form.querySelector('input[name="notification"]:checked');
+
+  if (!selected) {
+    errorMsg.textContent = "Please select a notification preference to continue.";
+    formField.classList.add("has-error");
+    return;
+  }
+
+  errorMsg.textContent = "";
+  formField.classList.remove("has-error");
+
+  showToast(`Saved! You'll receive notifications via ${LABELS[selected.value]}.`);
+});
+
+// Clear error once user makes a selection
+form.addEventListener("change", () => {
+  if (form.querySelector('input[name="notification"]:checked')) {
+    errorMsg.textContent = "";
+    formField.classList.remove("has-error");
+  }
+});
+
+function showToast(message) {
+  toastMessage.textContent = message;
+  toast.classList.add("visible");
+
+  if (toastTimer) clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => toast.classList.remove("visible"), 3500);
+}
+
